float stageHash(vec2 p) {
 return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);
}
vec2 shardSeed(int i,float layoutId,mat2 turnLayout) {
 vec2 seed=vec2(.04,.15);
 if(i==0)seed=vec2(.51,.49);
 if(i==1)seed=vec2(.09,.61);
 if(i==2)seed=vec2(.30,.89);
 if(i==3)seed=vec2(.77,.86);
 if(i==4)seed=vec2(.94,.48);
 if(i==5)seed=vec2(.80,.08);
 if(i==6)seed=vec2(.36,.10);
 if(i==8)seed=vec2(.52,.78);
 if(i==9)seed=vec2(.57,.18);
 float variation=step(.5,layoutId),fi=float(i);
 vec2 jitter=vec2(stageHash(vec2(fi+7.0,layoutId+51.0)),stageHash(vec2(fi+37.0,layoutId+83.0)))-.5;
 vec2 p=seed-vec2(.5);
 vec2 turned=turnLayout*p;
 vec2 changed=clamp(vec2(.5)+turned*.86+jitter*.16,vec2(.035),vec2(.965));
 return mix(seed,changed,variation);
}
// Distance from p to the bisector between a shard and one candidate neighbour
// (shard 0 is slightly larger). Unused or identical candidates never limit it.
float shardBisect(vec2 p,vec2 seed,float fi,vec2 other,float fj,float aspect) {
 if(fj<0.0||fj==fi)return 10.0;
 vec2 k=vec2(aspect,1.0),a=seed*k,b=other*k;
 float weighted=(fi==0.0?.028:0.0)-(fj==0.0?.028:0.0);
 return dot((a+b)*.5-p*k,normalize(b-a))+weighted;
}
mat2 shardRotation(float a) {
 float c=cos(a),s=sin(a);return mat2(c,-s,s,c);
}
vec3 filmDisplay(vec3 c) {
 c=max(c,vec3(0.0));
 return mix(c*12.92,1.055*pow(c,vec3(1.0/2.4))-.055,step(vec3(.0031308),c));
}
float filmDisplay1(float c) {
 c=max(c,0.0);
 return c<.0031308?c*12.92:1.055*pow(c,1.0/2.4)-.055;
}
vec3 filmLinear(vec3 c) {
 c=clamp(c,0.0,1.0);
 return mix(c/12.92,pow((c+.055)/1.055,vec3(2.4)),step(vec3(.04045),c));
}
vec3 dreamTap(vec2 p,float dream) {
 if(dream>=1.0)return vrchSampleSource0(p).rgb;
 if(dream<=0.0)return vrchSampleSource1(p).rgb;
 return mix(vrchSampleSource1(p).rgb,vrchSampleSource0(p).rgb,dream);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 float aspect=clamp(iResolution.x/iResolution.y,.75,2.5);
 vec2 scale=vec2(aspect,1.0);
 float phase=vrchPhase_speed(),hit=clamp(uParam_accent,0.0,1.0);
 float pulse=smoothstep(.22,.72,hit),gate=smoothstep(.30,.44,pulse);
 // Accumulated attacks form a performance phrase, with an unfiltered return at its end.
 float phrase=vrchPhase_accent()*4.0,act=mod(floor(phrase),6.0);
 float count=clamp(floor(uParam_shards+.5),3.0,10.0),groups=min(count,4.0);
 float group=mod(floor(phrase/2.0),groups),epoch=floor(phrase/6.0);
 // A layout is held for the entire opening. New paths are chosen while the scene is reassembled.
 float cycleTime=phase*.22+.45,cyclePhase=fract(cycleTime);
 float layoutId=floor(cycleTime)+floor(uParam_fracture+.5)*67.0;
 float variation=step(.5,layoutId);
 float fractureWindow=smoothstep(.04,.18,cyclePhase)*(1.0-smoothstep(.84,.98,cyclePhase));
 float separation=uParam_pressure,slip=uParam_bend;
 float nearest=-100.0,faceId=0.0,faceEdge=0.0,faceDepth=0.0,faceStagger=0.0,faceOpening=0.0;
 vec2 faceUV=uv,faceSeed=vec2(.5);
 // Select the visible shard before sampling either live image. A fragment moves
 // at most a fraction of a cell, so the three layout seeds nearest to this
 // pixel cover it, and only they bound each other's cells.
 vec2 s0=vec2(0.0),s1=vec2(0.0),s2=vec2(0.0);
 float i0=-1.0,i1=-1.0,i2=-1.0,d0=1e9,d1=1e9,d2=1e9;
 for(int k=0;k<10;k++) {
  if(float(k)>=count)break;
  // Seeds and every per-shard value come from this frame's frame stage.
  vec2 seed=vrchFrameData(k*3).xy;
  vec2 delta=(seed-uv)*scale;
  float dd=dot(delta,delta),fk=float(k);
  if(dd<d2) {
   if(dd<d1) {
    d2=d1;s2=s1;i2=i1;
    if(dd<d0){d1=d0;s1=s0;i1=i0;d0=dd;s0=seed;i0=fk;}
    else{d1=dd;s1=seed;i1=fk;}
   } else {d2=dd;s2=seed;i2=fk;}
  }
 }
 for(int c=0;c<3;c++) {
  float fi=c==0?i0:c==1?i1:i2;
  if(fi<0.0)continue;
  vec2 seed=c==0?s0:c==1?s1:s2;
  int ki=int(fi+.5)*3;
  vec4 shard=vrchFrameData(ki);
  float depth=shard.z,opening=shard.w;
  // A farther shard can never replace the current face, so skip its cell test.
  if(depth<=nearest)continue;
  vec4 motion=vrchFrameData(ki+1),shape=vrchFrameData(ki+2);
  vec2 local=seed+(mat2(motion.z,-motion.w,motion.w,motion.z)*((uv-seed)*scale-motion.xy))/scale/shape.x;
  local.x+=(local.y-seed.y)*shape.y;
  float edge=min(min(shardBisect(local,seed,fi,s0,i0,aspect),shardBisect(local,seed,fi,s1,i1,aspect)),
    shardBisect(local,seed,fi,s2,i2,aspect))
    -(.003+separation*.009)*opening;
  if(edge>0.0) {
   nearest=depth;faceUV=local;faceSeed=seed;faceId=fi;
   faceEdge=edge;faceDepth=depth;faceStagger=shape.z;faceOpening=opening;
  }
 }
 vec3 color=vec3(0.0);
 {
  // A face drawn at full weight replaces the background completely, so the
  // two background taps are only read where they still contribute.
  bool covered=nearest>-99.0&&uParam_amount>=1.0&&fractureWindow>=1.0;
  if(!covered) {
  vec4 sourceA=vrchSampleSource0(uv),sourceB=vrchSampleSource1(uv);
  vec3 background=mix(sourceB.rgb,sourceA.rgb,uParam_balance);
  fragColor=vec4(mix(sourceA.rgb,background,uParam_amount),mix(sourceA.a,1.0,uParam_amount));
  // Gaps show the background; combine it with the weighted fractured layer below.
  color=background;
  if(nearest<=-99.0) {
   fragColor.rgb+=uParam_amount*fractureWindow*(sourceB.rgb*.42-background);
   return;
  }
  }
 float echo=step(2.5,act)*(1.0-step(3.5,act));
 float tearing=step(.5,act)*(1.0-step(1.5,act));
 float chromatic=step(1.5,act)*(1.0-step(2.5,act));
 float returnToScene=step(4.5,act);
  float chosen=1.0-step(.5,abs(mod(faceId,groups)-group));
  float answer=1.0-step(.5,abs(mod(faceId+1.0,groups)-group));
  float lead=(chosen+answer)*(1.0-returnToScene)*faceOpening;
  float drift=sin(faceStagger*.57+faceId*1.1)+(uParam_balance-.5)*3.2;
  float dream=smoothstep(-.20,.20,drift);
  // Image swaps support the exposure accents while the scene remains spatially coherent.
  dream=mix(dream,1.0-dream,gate*chosen*(chromatic+echo*.55));
  float row=floor(faceUV.y*18.0),direction=stageHash(vec2(row,epoch+faceId))*2.0-1.0;
  float tornRow=step(.48,stageHash(vec2(row+7.0,floor(phrase)+faceId)));
  float glitch=uParam_drive*lead*(.18+.82*pulse)*(1.0-returnToScene*.85);
  vec2 q=faceUV+vec2(direction*tornRow*glitch*(.035+.105*tearing)/aspect,0.0);
  float hold=gate*tearing*lead*step(.72,stageHash(vec2(row+29.0,epoch)));
  q.x=mix(q.x,floor(q.x*24.0)/24.0,hold*.86);
  float spread=(.003+.032*uParam_light)*(glitch*.65+pulse*lead*.9)/aspect;
  // Registration and echo only use their extra samples when their weights are nonzero.
  bool split=lead*(uParam_drive*.45+pulse*.80)>0.0;
  bool ghostNeeded=gate*lead*echo>0.0;
  vec3 base=vec3(0.0),c=vec3(0.0),ghost=vec3(0.0);
  float leftRed=0.0,rightBlue=0.0;
  // A fully dreamed or fully present tap reads only one live image.
  base=dreamTap(q,dream);
  if(split) {
   leftRed=dreamTap(q+vec2(spread,0.0),dream).r;
   rightBlue=dreamTap(q-vec2(spread,0.0),dream).b;
  }
  if(ghostNeeded)ghost=dreamTap(q+vec2(.065*lead/aspect,-.009),1.0-dream);
  vec3 ink=mod(faceId,2.0)<.5?vec3(.05,.92,.96):vec3(1.0,.10,.58);
  // The untouched state stays on the original linear image path; a face with
  // neither registration nor exposure returns to it unchanged.
  vec3 face=base;
  float exposure=gate*lead;
  if(uParam_drive+hit>=.00001&&(split||exposure>0.0)) {
  c=filmDisplay(base);
  if(split) {
   c=mix(c,vec3(filmDisplay1(leftRed),c.g,filmDisplay1(rightBlue)),clamp(lead*(uParam_drive*.45+pulse*.80),0.0,1.0));
  }
  // Every exposure treatment is weighted by exposure; at zero it leaves c unchanged.
  if(exposure>0.0) {
  float negative=1.0-step(.5,act);
  float solar=step(3.5,act)*(1.0-step(4.5,act));
  ghost=filmDisplay(ghost);
  vec3 inverted=vec3(1.0)-c;
  c=mix(c,inverted*vec3(.92,.97,1.0),exposure*negative);
  float lum=dot(c,vec3(.2126,.7152,.0722));
  vec3 opposite=mod(faceId,2.0)<.5?vec3(.38,.01,.32):vec3(.01,.21,.30);
  vec3 duotone=mix(opposite,ink,smoothstep(.08,.9,lum));
  c=mix(c,duotone,exposure*chromatic*.94);
  vec3 doubleExposure=clamp(c*.44+(vec3(1.0)-ghost)*vec3(.18,.92,.98)*.88,0.0,1.0);
  float scan=.76+.24*step(.42,fract(faceUV.y*min(iResolution.y*.32,160.0)));
  c=mix(c,doubleExposure*scan,exposure*echo*.92);
  vec3 solarized=mix(c,1.0-c,smoothstep(vec3(.40),vec3(.64),c));
  solarized=clamp((solarized-.12)*2.35,0.0,1.0);
  c=mix(c,solarized*mix(vec3(.55,.98,1.0),vec3(1.0,.24,.64),step(.5,mod(faceId,2.0))),exposure*solar);
  float dropout=tornRow*gate*tearing*lead;
  vec3 dropoutInk=mix(c*.12,ink*(.20+lum*.80),step(.82,stageHash(vec2(row,floor(q.x*27.0)))));
  c=mix(c,dropoutInk,dropout*.88);
  }
  face=filmLinear(c);
  }
  face*=.85+.15*faceDepth;
  float aa=1.0/iResolution.y,rim=1.0-smoothstep(aa,aa*2.5,faceEdge);
  float inner=exp(-faceEdge/(.009+.011*separation));
  vec3 edgeColor=mix(vec3(.34,.48,.58),vec3(.65,.51,.31),dream);
  vec3 inkLinear=mod(faceId,2.0)<.5?vec3(0.003936,0.827571,0.911408):vec3(1.,0.010023,0.2957);
  edgeColor=mix(edgeColor,inkLinear,pulse*lead*.82);
  face+=edgeColor*(inner*(.06+uParam_light*.25)+rim*(.12+uParam_light*.50))*faceOpening;
  if(covered)fragColor=vec4(face,1.0);
  else fragColor.rgb+=uParam_amount*fractureWindow*(face-color);
 }
}

frame.source:
// Per-shard values for this frame, three texels per shard:
// 0 seed.xy, depth, opening; 1 shift.xy, cos and sin of the turn; 2 zoom, skew, stagger.
void vrchFrame(in int texel,out vec4 value) {
 int k=texel/3,part=texel-k*3;
 float aspect=clamp(iResolution.x/iResolution.y,.75,2.5);
 vec2 scale=vec2(aspect,1.0);
 float phase=vrchPhase_speed(),pulse=smoothstep(.22,.72,clamp(uParam_accent,0.0,1.0));
 float phrase=vrchPhase_accent()*4.0;
 float count=clamp(floor(uParam_shards+.5),3.0,10.0),groups=min(count,4.0);
 float group=mod(floor(phrase/2.0),groups);
 float cycleTime=phase*.22+.45,cyclePhase=fract(cycleTime);
 float layoutId=floor(cycleTime)+floor(uParam_fracture+.5)*67.0;
 float variation=step(.5,layoutId);
 float separation=uParam_pressure,slip=uParam_bend;
 float layoutAngle=(stageHash(vec2(layoutId,31.0))-.5)*6.2831853;
 mat2 turnLayout=mat2(cos(layoutAngle),-sin(layoutAngle),sin(layoutAngle),cos(layoutAngle));
 float fi=float(k);
 vec2 seed=variation>.5?shardSeed(k,layoutId,turnLayout):shardSeed(k,0.0,mat2(1.0));
 vec2 travel=normalize((seed-vec2(.49,.47))*scale+vec2(.14,.035));
 float launch=(stageHash(vec2(fi+19.0,layoutId+11.0))-.5)*1.7*variation;
 travel=shardRotation(launch)*travel;
 float order=stageHash(vec2(fi+23.0,layoutId+43.0));
 float closeOrder=stageHash(vec2(fi+67.0,layoutId+89.0));
 float opening=smoothstep(.04+order*.20,.20+order*.20,cyclePhase)
   *(1.0-smoothstep(.72+closeOrder*.12,.96,cyclePhase));
 float stagger=phase*.68-seed.x*2.2-seed.y*.8
   +(stageHash(vec2(fi+41.0,layoutId+17.0))-.5)*4.0*variation;
 float release=.5+.5*tanh(2.1*sin(stagger));
 float depth=.2+.55*release+.12*sin(fi*2.3);
 float chosen=1.0-step(.5,abs(mod(fi,groups)-group));
 float distance=separation*(.045+.085*release);
 vec2 shift=travel*distance+vec2(.032,-.015)*sin(stagger+fi*.4)*slip;
 shift+=vec2(group<1.5?.022:-.022,0.0)*chosen*uParam_drive*(.24+.76*pulse);
 shift*=opening;
 float angle=(seed.y-.5)*(slip*.26)*sin(stagger+.6)*opening;
 float zoom=1.0+depth*separation*.17*opening;
 float skew=slip*.13*sin(stagger*.77)*opening;
 if(part==0)value=vec4(seed,depth,opening);
 else if(part==1)value=vec4(shift,cos(angle),sin(angle));
 else value=vec4(zoom,skew,stagger,0.0);
}
